(14, 1, '2026-08-18 04:41:31', '2026-08-18 01:41:31', '<!-- wp:paragraph -->\n<p><strong>Виртуальная экскурсия по Мемориальному дому-музею Николая Рубцова в селе Никольском Вологодской области.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Познакомьтесь с жизнью и творчеством Николая Рубцова, его судьбой, литературным наследием и местами, связанными с жизнью поэта.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>В рамках экскурсии можно будет посетить виртуальную экспозицию и познакомиться с материалами:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>«Жизненный путь Николая Рубцова»</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>«Мемориальная комната поэта»</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>[ ФОТО МЕМОРИАЛЬНОГО ДОМА-МУЗЕЯ НИКОЛАЯ РУБЦОВА </strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<div class=\"museum-placeholder\">\n    <span>\n        ФОТО МЕМОРИАЛЬНОГО ДОМА-МУЗЕЯ<br>\n        НИКОЛАЯ РУБЦОВА\n    </span>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><strong>Жизненный путь Николая Рубцова</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Николай Михайлович Рубцов — русский советский поэт, чьё творчество связано с темами родины, природы, памяти и человеческой судьбы.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>В этом разделе будет представлена виртуальная экспозиция, посвящённая основным этапам жизни поэта, его творческому пути и событиям, повлиявшим на его произведения.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<div class=\"museum-placeholder\">\n    <span>\n        ЭКСПОЗИЦИЯ<br>\n        «ЖИЗНЕННЫЙ ПУТЬ НИКОЛАЯ РУБЦОВА»\n    </span>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Мемориальная комната поэта</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Мемориальная комната позволяет познакомиться с атмосферой, в которой жил и работал Николай Рубцов. Здесь будут представлены предметы, фотографии и другие материалы, связанные с жизнью поэта.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<div class=\"museum-placeholder\">\n    <span>\n        ЭКСПОЗИЦИЯ<br>\n        «МЕМОРИАЛЬНАЯ КОМНАТА ПОЭТА»\n    </span>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Цифровая экскурсия «Биография и творчество поэта»', '', 'publish', 'closed', 'closed', '', '%d0%b1%d0%b8%d0%be%d0%b3%d1%80%d0%b0%d1%84%d0%b8%d1%8f-%d0%b8-%d1%82%d0%b2%d0%be%d1%80%d1%87%d0%b5%d1%81%d1%82%d0%b2%d0%be-%d0%bf%d0%be%d1%8d%d1%82%d0%b0', '', '', '2026-08-18 05:35:16', '2026-08-18 02:35:16', '', 0, 'http://app.ru/WordPress/wordpress/?post_type=museum_subsection&#038;p=14', 0, 'museum_subsection', '', 0),
