(44, 1, '2026-08-18 16:47:27', '2026-08-18 13:47:27', '<!-- wp:paragraph -->\n<p>Церемония награждения победителей Московского конкурса детского рисунка имени Нади Рушевой 2025-2026 учебного года</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>28 августа 2026 г. в 17:00</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Церемония награждения победителей (1 степень) пройдет в выставочном зале ЦНХО ИНО МГПУ по адресу: ул. Касаткина, дом 1.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>2 поток&nbsp;&nbsp;с 17:00 до 19:00 (учащиеся 5-11 классов)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":45,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://app.ru/WordPress/wordpress/wp-content/uploads/2026/08/1783588917-1024x565.png\" alt=\"\" class=\"wp-image-45\"/></figure>\n<!-- /wp:image -->', 'Московского конкурса детского рисунка', '', 'publish', 'closed', 'closed', '', '%d0%bc%d0%be%d1%81%d0%ba%d0%be%d0%b2%d1%81%d0%ba%d0%be%d0%b3%d0%be-%d0%ba%d0%be%d0%bd%d0%ba%d1%83%d1%80%d1%81%d0%b0-%d0%b4%d0%b5%d1%82%d1%81%d0%ba%d0%be%d0%b3%d0%be-%d1%80%d0%b8%d1%81%d1%83%d0%bd', '', '', '2026-08-18 16:47:27', '2026-08-18 13:47:27', '', 0, 'http://app.ru/WordPress/wordpress/?post_type=museum_event&#038;p=44', 0, 'museum_event', '', 0),
